{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'financials' does not have versioning enabled, which can lead to data loss in case of accidental deletion or overwrite."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'financials' does not have a Public Access block configured, which can expose the bucket to unauthorized public access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"financials\" {\n  bucket        = \"${local.resource_prefix.value}-financials\"\n  acl           = \"private\"\n  force_destroy = true\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-financials\"\n    Environment = local.resource_prefix.value\n    }, {\n  })\n  versioning {\n    enabled = true\n  }\n}\nresource \"aws_s3_bucket_public_access_block\" \"financials\" {\n  bucket = aws_s3_bucket.financials.id\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled versioning for the S3 bucket 'financials' and added a Public Access block to restrict public access."
}
